public class NumberDescriber {

    public static String describe(int n) {
        if (n == 0) {
            return "zero";
        }
        String size;
        if (Math.abs(n) <= 10) {
            size = "small";
        } else {
            size = "large";
        }
        if (n % 2 == 0) {
            return size + " even";
        } else {
            return size + " odd";
        }
    }
}
